"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { eventFiles } from "@lexical/rich-text";
import { mergeRegister } from "@lexical/utils";
import {
  COMMAND_PRIORITY_CRITICAL,
  COMMAND_PRIORITY_NORMAL,
  DRAGOVER_COMMAND,
  DROP_COMMAND,
} from "lexical";
import { useEffect, useRef } from "react";
import type { RefObject } from "react";

import { focusDroppedBlock, moveDraggedBlock } from "./drop-placement";
import {
  hideTargetLine,
  isOnBlockDragHandleTarget,
  positionTargetLine,
  readBlockDragKey,
  resolveDropTarget,
} from "./drop-target";

interface BlockDragStabilizerProps {
  anchorElem: HTMLElement;
  menuRef: RefObject<HTMLElement | null>;
  targetLineRef: RefObject<HTMLElement | null>;
}

/**
 * Companion to the experimental upstream drag-handle plugin, which keeps
 * owning the handle/line rendering and hover tracking. The stabilizer takes
 * over the drop path at higher command priorities to fix three defects the
 * upstream version has in a window-scrolled editor:
 *
 * - before/after math mixes `pageY` (document space) with viewport rects,
 *   so scrolled drops always land "after" — every comparison here uses
 *   `clientX`/`clientY`.
 * - post-drop focus/selection restore only runs on Firefox — here the
 *   selection moves onto the dropped block on every browser.
 * - pressing the handle blurs the editor, so the caret goes stale; the drop
 *   handler below moves the selection onto the dropped block in the same
 *   update that moves it, which keeps the reconciler from scrolling a stale,
 *   off-screen caret into view.
 *
 * Drags that did not start from the handle (text selections, files) return
 * `false` untouched so their default handlers keep working.
 *
 * Note: the handle mousedown must NOT be preventDefault-ed — Chromium treats
 * a canceled mousedown as "don't start a native drag" and `dragstart` never
 * fires.
 */
export function BlockDragStabilizer({
  anchorElem,
  menuRef,
  targetLineRef,
}: BlockDragStabilizerProps) {
  const [editor] = useLexicalComposerContext();
  const ownDragRef = useRef(false);

  useEffect(() => {
    const onDragStartCapture = (event: DragEvent) => {
      const menu = menuRef.current;
      const { target } = event;
      ownDragRef.current = isOnBlockDragHandleTarget(target, menu);
    };
    const onDragEndCapture = () => {
      ownDragRef.current = false;
      hideTargetLine(targetLineRef.current);
    };

    window.addEventListener("dragstart", onDragStartCapture, true);
    window.addEventListener("dragend", onDragEndCapture, true);
    window.addEventListener("drop", onDragEndCapture, true);

    return () => {
      window.removeEventListener("dragstart", onDragStartCapture, true);
      window.removeEventListener("dragend", onDragEndCapture, true);
      window.removeEventListener("drop", onDragEndCapture, true);
    };
  }, [menuRef, targetLineRef]);

  useEffect(
    () =>
      mergeRegister(
        editor.registerCommand(
          DRAGOVER_COMMAND,
          (event: DragEvent) => {
            if (!ownDragRef.current) {
              return false;
            }

            const [isFileTransfer] = eventFiles(event);

            if (isFileTransfer) {
              return false;
            }

            if (!(event.target instanceof HTMLElement)) {
              return false;
            }

            const target = resolveDropTarget(
              editor,
              anchorElem,
              event.clientX,
              event.clientY,
              true
            );
            const line = targetLineRef.current;

            if (target === null || line === null) {
              return false;
            }

            positionTargetLine(line, target, event.clientY, anchorElem);
            event.preventDefault();
            return true;
          },
          COMMAND_PRIORITY_NORMAL
        ),
        editor.registerCommand(
          DROP_COMMAND,
          (event: DragEvent) => {
            const [isFileTransfer] = eventFiles(event);

            if (isFileTransfer) {
              return false;
            }

            const draggedKey = readBlockDragKey(event.dataTransfer);

            if (draggedKey === null) {
              return false;
            }

            if (!(event.target instanceof HTMLElement)) {
              return false;
            }

            const target = resolveDropTarget(
              editor,
              anchorElem,
              event.clientX,
              event.clientY,
              true
            );

            if (target === null) {
              return false;
            }

            const moved = moveDraggedBlock(
              editor,
              draggedKey,
              target,
              event.clientY,
              (movedElement) => {
                focusDroppedBlock(editor, movedElement);
              }
            );
            hideTargetLine(targetLineRef.current);
            ownDragRef.current = false;

            if (!moved) {
              return false;
            }

            // Claim the drop: without this the browser performs its native
            // drop action afterwards (drop-caret placement, navigation for
            // exotic payloads), yanking the caret/scroll away from the
            // dropped block we just selected. Focus/scroll itself runs in
            // the move's onUpdate, after the DOM commit lands.
            event.preventDefault();
            return true;
          },
          COMMAND_PRIORITY_CRITICAL
        )
      ),
    [anchorElem, editor, targetLineRef]
  );

  return null;
}

"use client";

import type { LexicalEditor, LexicalNode } from "lexical";
import {
  $createNodeSelection,
  $getNearestNodeFromDOMNode,
  $getNodeByKey,
  $isElementNode,
  $setSelection,
} from "lexical";

import { decideInsertAfter } from "./drop-target";

/**
 * Moves the caret onto the dropped block inside the same update that moves
 * it. Element blocks get a collapsed caret at their start; decorator blocks
 * (images, embeds, dividers) get a node selection, matching click-to-select.
 * Keeping selection glued to the moved node is what stops the reconciler
 * from scrolling a stale, off-screen caret into view after the drop.
 */
function selectDroppedNode(node: LexicalNode): void {
  if ($isElementNode(node)) {
    node.selectStart();
    return;
  }

  const selection = $createNodeSelection();
  selection.add(node.getKey());
  $setSelection(selection);
}

/**
 * Moves the dragged top-level block before/after the drop target (resolved
 * in viewport space) and parks the selection on it.
 *
 * DROP_COMMAND listeners run inside Lexical's own outer update
 * (`triggerCommandListeners` wraps every priority level in
 * `updateEditorSync`), so this `editor.update` is a *nested* update: the DOM
 * move only commits when the outer update flushes, after this listener
 * returns. Reading layout or scrolling synchronously here would therefore
 * observe the pre-move DOM. Pass `onMoved` to run focus/scroll work after
 * the commit, when `editor.getElementByKey` resolves to the moved element
 * with fresh layout. Returns `true` when the payload referenced live nodes
 * and the drop was claimed.
 */
export function moveDraggedBlock(
  editor: LexicalEditor,
  draggedKey: string,
  targetElem: HTMLElement,
  clientY: number,
  onMoved?: (element: HTMLElement) => void
): boolean {
  let claimed = false;

  editor.update(
    () => {
      const draggedNode = $getNodeByKey(draggedKey);
      const targetNode = $getNearestNodeFromDOMNode(targetElem);

      if (draggedNode === null || targetNode === null) {
        return;
      }

      claimed = true;

      if (targetNode.getKey() !== draggedNode.getKey()) {
        const targetTop = targetElem.getBoundingClientRect().top;

        if (decideInsertAfter(clientY, targetTop)) {
          targetNode.insertAfter(draggedNode);
        } else {
          targetNode.insertBefore(draggedNode);
        }
      }

      selectDroppedNode(draggedNode);
    },
    {
      discrete: true,
      onUpdate: () => {
        if (!claimed || onMoved === undefined) {
          return;
        }

        const movedElement = editor.getElementByKey(draggedKey);

        if (movedElement !== null) {
          onMoved(movedElement);
        }
      },
    }
  );

  return claimed;
}

/**
 * Hands DOM focus back to the editor without scrolling, then reveals the
 * dropped block only when it is actually outside the viewport. The drop
 * point is visible by definition, so an unconditional `scrollIntoView` would
 * yank the viewport away from where the user just dropped the block; the
 * nearest-edge scroll is purely a fallback for edge-clamped drops whose
 * target resolved off-screen. This runs on every browser (the upstream
 * experimental plugin only restores focus on Firefox), so the caret
 * genuinely lands where the block did.
 */
export function focusDroppedBlock(
  editor: LexicalEditor,
  element: HTMLElement
): void {
  editor.getRootElement()?.focus({ preventScroll: true });

  const { bottom, top } = element.getBoundingClientRect();
  const viewportHeight =
    element.ownerDocument.defaultView?.innerHeight ?? window.innerHeight;

  if (top < 0 || bottom > viewportHeight) {
    element.scrollIntoView({ block: "nearest", inline: "nearest" });
  }
}

"use client";

import { calculateZoomLevel } from "@lexical/utils";
import type { LexicalEditor } from "lexical";
import { $getRoot } from "lexical";

/**
 * DataTransfer payload that identifies a handle-initiated block drag. This
 * mirrors the experimental upstream plugin, which owns `dragstart` and writes
 * this entry — the stabilizer only *reads* it on drop.
 */
export const DRAG_DATA_FORMAT = "application/x-lexical-drag-block";

const TARGET_LINE_HALF_HEIGHT = 2;
const TEXT_BOX_HORIZONTAL_PADDING = 28;
const MENU_SPACE = 4;

export function isOnBlockDragHandleTarget(
  target: EventTarget | null,
  menu: HTMLElement | null
): boolean {
  return menu !== null && target instanceof Node && menu.contains(target);
}

const SEARCH_UP = -1;
const SEARCH_DOWN = 1;
const SEARCH_UNDECIDED = 0;

// Remembers the last hit so consecutive dragover resolutions start nearby
// instead of scanning from the middle of the document every time.
let prevIndex = Infinity;

function getSearchStart(keysLength: number): number {
  if (keysLength === 0) {
    return Infinity;
  }

  if (prevIndex >= 0 && prevIndex < keysLength) {
    return prevIndex;
  }

  return Math.floor(keysLength / 2);
}

function safeMargin(value: string | undefined): number {
  // getComputedStyle normalizes margins to "<number>px" (or "").
  const parsed = Number((value ?? "").replace("px", ""));
  return Number.isNaN(parsed) ? 0 : parsed;
}

function effectiveZoom(element: HTMLElement): number {
  // calculateZoomLevel can report 0/NaN where CSS zoom is unsupported
  // (e.g. synthetic DOMs); viewport math needs a sane divisor.
  return calculateZoomLevel(element) || 1;
}

function getCollapsedMargins(element: HTMLElement): {
  marginBottom: number;
  marginTop: number;
} {
  const view = element.ownerDocument.defaultView;
  const getMargin = (
    sibling: Element | null,
    margin: "marginBottom" | "marginTop"
  ): number => {
    if (sibling === null || view === null) {
      return 0;
    }

    return safeMargin(view.getComputedStyle(sibling)[margin]);
  };
  const style = view?.getComputedStyle(element);

  return {
    marginBottom: Math.max(
      safeMargin(style?.marginBottom ?? ""),
      getMargin(element.nextElementSibling, "marginTop")
    ),
    marginTop: Math.max(
      safeMargin(style?.marginTop ?? ""),
      getMargin(element.previousElementSibling, "marginBottom")
    ),
  };
}

/**
 * Reads the dragged block key from a drop event. Returns `null` for drags
 * that did not originate from the block handle (text selections, files),
 * which must keep flowing to the default handlers.
 */
export function readBlockDragKey(
  dataTransfer: DataTransfer | null | undefined
): string | null {
  if (!dataTransfer) {
    return null;
  }

  try {
    const key = dataTransfer.getData(DRAG_DATA_FORMAT);
    return key === "" ? null : key;
  } catch {
    return null;
  }
}

/**
 * Decides whether the dragged block lands after the target block. Pure on
 * viewport coordinates: `clientY` and `getBoundingClientRect().top` share
 * the same origin, unlike `pageY` which also carries the page scroll offset
 * and would force "after" whenever the page is scrolled.
 */
export function decideInsertAfter(clientY: number, targetTop: number): boolean {
  return clientY >= targetTop;
}

/**
 * Clamps out-of-document cursor positions to the first/last block, in
 * viewport space.
 */
function matchEdgeBlock(
  editor: LexicalEditor,
  topLevelKeys: string[],
  clientY: number
): HTMLElement | null {
  const lastKey = topLevelKeys.at(-1);

  if (topLevelKeys.length === 0 || lastKey === undefined) {
    return null;
  }

  const firstNode = editor.getElementByKey(topLevelKeys[0]);
  const lastNode = editor.getElementByKey(lastKey);
  const firstRect = firstNode?.getBoundingClientRect();
  const lastRect = lastNode?.getBoundingClientRect();

  if (!firstNode || !lastNode || !firstRect || !lastRect) {
    return null;
  }

  if (clientY / effectiveZoom(firstNode) < firstRect.top) {
    return firstNode;
  }

  if (clientY / effectiveZoom(lastNode) > lastRect.bottom) {
    return lastNode;
  }

  return null;
}

/**
 * Walks the top-level blocks from the last hit toward the viewport point.
 */
function walkBlocks(
  editor: LexicalEditor,
  anchorElem: HTMLElement,
  topLevelKeys: string[],
  clientX: number,
  clientY: number
): HTMLElement | null {
  const anchorRect = anchorElem.getBoundingClientRect();
  let index = getSearchStart(topLevelKeys.length);
  let direction = SEARCH_UNDECIDED;

  while (index >= 0 && index < topLevelKeys.length) {
    const elem = editor.getElementByKey(topLevelKeys[index]);

    if (elem === null) {
      return null;
    }

    const zoom = effectiveZoom(elem);
    const pointX = clientX / zoom;
    const pointY = clientY / zoom;
    const rect = elem.getBoundingClientRect();
    const { marginBottom, marginTop } = getCollapsedMargins(elem);
    const top = rect.top - marginTop;
    const bottom = rect.bottom + marginBottom;
    const inside =
      pointY >= top &&
      pointY <= bottom &&
      pointX >= anchorRect.left &&
      pointX <= anchorRect.right;

    if (inside) {
      prevIndex = index;
      return elem;
    }

    if (direction === SEARCH_UNDECIDED) {
      if (pointY < top) {
        direction = SEARCH_UP;
      } else if (pointY > bottom) {
        direction = SEARCH_DOWN;
      } else {
        // Horizontally outside the text column: no block can match.
        return null;
      }
    }

    index += direction;
  }

  return null;
}

/**
 * Resolves the top-level block element under viewport point
 * (`clientX`, `clientY`). Same search shape as the experimental upstream
 * plugin, but every comparison stays in viewport space so the hit stays
 * correct while the page is scrolled.
 */
export function resolveDropTarget(
  editor: LexicalEditor,
  anchorElem: HTMLElement,
  clientX: number,
  clientY: number,
  useEdgeAsDefault = false
): HTMLElement | null {
  const topLevelKeys = editor
    .getEditorState()
    .read(() => $getRoot().getChildrenKeys());

  return editor.getEditorState().read(() => {
    if (useEdgeAsDefault) {
      const edge = matchEdgeBlock(editor, topLevelKeys, clientY);

      if (edge !== null) {
        return edge;
      }
    }

    return walkBlocks(editor, anchorElem, topLevelKeys, clientX, clientY);
  });
}

/**
 * Positions the drop indicator line relative to the target block, using the
 * viewport-space cursor (`clientY`) for the before/after side.
 */
export function positionTargetLine(
  targetLineElem: HTMLElement,
  targetBlockElem: HTMLElement,
  clientY: number,
  anchorElem: HTMLElement
): void {
  const { height: targetHeight, top: targetTop } =
    targetBlockElem.getBoundingClientRect();
  const { top: anchorTop, width: anchorWidth } =
    anchorElem.getBoundingClientRect();
  const { marginBottom, marginTop } = getCollapsedMargins(targetBlockElem);

  let lineTop = targetTop;

  if (clientY >= targetTop) {
    lineTop += targetHeight + marginBottom / 2;
  } else {
    lineTop -= marginTop / 2;
  }

  const top =
    lineTop - anchorTop - TARGET_LINE_HALF_HEIGHT + anchorElem.scrollTop;
  const left = TEXT_BOX_HORIZONTAL_PADDING - MENU_SPACE;

  targetLineElem.style.transform = `translate(${left}px, ${top}px)`;
  targetLineElem.style.width = `${anchorWidth - (TEXT_BOX_HORIZONTAL_PADDING - MENU_SPACE) * 2}px`;
  targetLineElem.style.opacity = ".4";
}

export function hideTargetLine(
  targetLineElem: HTMLElement | null | undefined
): void {
  if (targetLineElem) {
    targetLineElem.style.opacity = "0";
    targetLineElem.style.transform = "translate(-10000px, -10000px)";
  }
}

import type { ExtraEditorFeature } from "../../core/types";
import { DraggableBlockPlugin } from "./plugin";

/**
 * Installs the drag-handle block controls. The plugin self-gates on editor
 * editability, so mounting it in read-only mode is a no-op. Ships as the
 * `editor-draggable-blocks` registry item.
 */
export const draggableBlocksFeature: ExtraEditorFeature = {
  id: "draggable-blocks",
  plugin: DraggableBlockPlugin,
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { DraggableBlockPlugin_EXPERIMENTAL as DraggableBlockPluginExperimental } from "@lexical/react/LexicalDraggableBlockPlugin";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { GripVerticalIcon } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { BlockDragStabilizer } from "./drag-stabilizer";

const DRAG_MENU_CLASS_NAME = "editor-draggable-block-menu";

const isOnMenu = (element: HTMLElement) =>
  Boolean(element.closest(`.${DRAG_MENU_CLASS_NAME}`));

export function DraggableBlockPlugin() {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const menuRef = useRef<HTMLDivElement>(null);
  const targetLineRef = useRef<HTMLDivElement>(null);
  const [anchorElem, setAnchorElem] = useState<HTMLElement | null>(null);

  useEffect(
    () =>
      editor.registerRootListener((rootElement) => {
        setAnchorElem(rootElement?.parentElement ?? null);
      }),
    [editor]
  );

  if (!(isEditable && anchorElem)) {
    return null;
  }

  return (
    <>
      <DraggableBlockPluginExperimental
        anchorElem={anchorElem}
        isOnMenu={isOnMenu}
        menuComponent={
          <div
            className={`${DRAG_MENU_CLASS_NAME} absolute top-0 left-0 z-40 flex cursor-grab items-center gap-0.5 rounded-md p-0.5 text-muted-foreground opacity-0 transition-transform-opacity duration-150 ease-in-out active:cursor-grabbing`}
            ref={menuRef}
          >
            <div className="flex size-4 items-center justify-center rounded-sm opacity-50 transition hover:bg-muted hover:opacity-100">
              <GripVerticalIcon className="size-3.5" />
            </div>
          </div>
        }
        menuRef={menuRef}
        targetLineComponent={
          <div
            className="pointer-events-none absolute top-0 left-0 z-30 h-1 rounded-full bg-primary opacity-0"
            ref={targetLineRef}
          />
        }
        targetLineRef={targetLineRef}
      />
      <BlockDragStabilizer
        anchorElem={anchorElem}
        menuRef={menuRef}
        targetLineRef={targetLineRef}
      />
    </>
  );
}
